import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import type { Person } from '../people/people';
import { useSnapshotLines } from './snapshots';

function SnapshotHeader() {
  return <th>Snapshots</th>;
}

// The person's snapshot lines: one per SNAPSHOT written for them as the sheet's today moved, oldest first, as the
// day being left and their due-total on it.
function PersonSnapshots({ sheet, person }: { sheet: string; user: string; person: Person }) {
  const { data: lines = [] } = useSnapshotLines(sheet);
  return (
    <td>
      {lines
        .filter((l) => l.person === person.id)
        .map((l, i) => (
          <div key={i} data-testid="person-snapshot-line">
            {l.day} {l.dueTotal}
          </div>
        ))}
    </td>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 80, Component: SnapshotHeader }),
  PersonColumns.fill({ order: 80, Component: PersonSnapshots }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** One of `person`'s snapshot lines: the day being left (yyyy-mm-dd) when the sheet's today moved, and their
 *  due-total on it (two decimals, or n/a). */
export type SnapshotLine = { person: number; day: string; dueTotal: string };

export const snapshotLinesKey = (sheet: string) => ['snapshot-lines', sheet] as const;

export const snapshotLinesPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/snapshot-lines`;

/** Every snapshot line on the sheet, oldest first. */
export function useSnapshotLines(sheet: string) {
  return useQuery({
    queryKey: snapshotLinesKey(sheet),
    queryFn: () => getJson<SnapshotLine[]>(snapshotLinesPath(sheet)),
  });
}
